-- Import des courriers départs 2026
-- Source : depart/2026.xlsx (feuille Feuil1).
-- Ce fichier ne reprend pas 2002-2025. Il s'ajoute à import_departs_2002_2025.sql.
--
-- Colonnes :
--   N° DOSSIER            -> txt_referencecourierdepartcd (« Dossier <n> »)
--                          Le numéro se répète : il ne sert pas de numéro d'ordre.
--                          Plusieurs destinataires le même jour -> BE à réponses Multiples
--                          Un seul destinataire -> Individuel
--   DATE DEPART           -> dt_datecouriercd et dt_dateenvoicd
--   PRENOMS + NOM         -> txt_prenomNomcd et txt_destinatairecd
--   SITUATION/LOTISSEMENT -> txt_lotissementcd
--   DESIGNATION           -> txt_objetcd
--   N° TF                 -> txt_numTitreFonciercd
--   N° LOT                -> txt_numLotcd
--   SUPERFICIE            -> txt_superficiecd si c'est un nombre
--   NICAD                 -> ajouté à l'observation
--   ANCIEN TITRES         -> sert au rapprochement (titre mère) et à l'observation
--   OBSERVATIONS          -> txt_observationcd (souvent le visa V/LN°)
--
-- Même terrain qu'une arrivée importée :
--   numéro du titre (ou ancien titre, ou titre mère) et même lot.
--   15/S et S 15 sont le même lot. Arrivée la plus récente avant le départ,
--   de préférence au même nom.
--   txt_referencecourierarriveecd = txt_reference, à l'identique.
--   Catégorie Reponse à un Courrier arrivé, ou Dossier Retourne si le libellé
--   ou l'observation commence par Retour.
--   Durée comme le formulaire, sauf arrivée au 1er janvier ou avant 1990.
--
-- N° d'ordre 2026 : 0001 à 0832, dans l'ordre des dates.
-- Référence : <n°>/MFB/DGID/CSF/CSF-NGA/BCAD du jj-mm-aaaa
--
-- Lignes importées : 832
-- Lignes non importées : 0
-- Lien :
--     486  réponses reliées
--     353  même nom
--     133  même terrain, nom différent
--     346  départs simples
--     486  durées calculées
--     246  superficies
--     483  lotissements
--       2  n° de dossier foncier repris
--      33  NICAD
--      35  anciens titres
-- Catégories :
--     475  Reponse à un Courrier arrivé
--     188  (sans catégorie)
--     147  Demande
--      14  Dossier Retourne
--       4  Information
--       4  Transmission de Documents
-- Types :
--     505  BE à réponses Multiples
--     327  Individuel

SET NAMES utf8mb4;

ALTER TABLE `departs`
  MODIFY `txt_numLotcd` VARCHAR(120) NULL,
  MODIFY `txt_numTitreFonciercd` VARCHAR(255) NULL,
  MODIFY `txt_numdossiercd` VARCHAR(50) NULL,
  MODIFY `txt_observationcd` TEXT NULL;

START TRANSACTION;






COMMIT;
